import type { Weather } from '../engine/weather'
import type { Layout } from './layout'
import { fbm, hashOf, lattice, mulberry, valueNoise } from './noise'

/** Which weather layers are drawn; each toggles on its own and they add. */
export type Layers = { code: boolean; impact: boolean; risk: boolean; history: boolean }

export const ALL_LAYERS: Layers = { code: true, impact: true, risk: true, history: true }

/**
 * The layers a session starts with. History's rings are off until `4` turns them on: backtested,
 * about half of them name a file the change left out (bench/history.mts).
 */
export const DEFAULT_LAYERS: Layers = { ...ALL_LAYERS, history: false }

/** The weather field in half-block pixels: x in columns, y in half rows, RGB 0..255. */
export type Field = {
  w: number
  h: number
  /** radar bin per pixel, 0 (dry) to 9 (the eye); the palette colours it */
  level: Uint8Array
  /** 1 where the reach's rain sets the pixel's bin rather than a storm: it takes the rain's own hue */
  wet: Uint8Array
  /** where each edit's eye is drawn, as a glyph over the weather */
  eyes: { path: string; x: number; y: number; risk: number; isLatest: boolean }[]
  /** where history expected a change: drawn as dashed braille contours over the weather */
  rings: { path: string; region: string; x: number; y: number; share: number }[]
  /** the offshoot's track: evenly spaced stops from the storm to the farthest file, drawn as ink dots */
  track: { x: number; y: number }[]
}

import { BINS, COOL_TOP, RAIN_TOP, STORM } from './palette'

type Puff = { x: number; y: number; sx: number; sy: number; amp: number }

/** The storm, rain and marks of `weather` over `layout`, as radar bins any ground can colour. */
export function fieldOf(layout: Layout, weather: Weather | null, layers: Layers, seedText: string): Field {
  const w = layout.cols
  const h = layout.rows * 2
  const level = new Uint8Array(w * h)
  const wet = new Uint8Array(w * h)
  const seed = hashOf(seedText)

  if (weather === null) return { w, h, level, wet, eyes: [], rings: [], track: [] }

  const rnd = mulberry(seed)
  const pointOf = placer(layout, seed)
  const storm: Puff[] = []
  const rain: Puff[] = []

  // the riskiest edit of the latest turn is the lead storm and alone reaches the hottest bins;
  // the rest burn a step cooler, and an earlier turn's edits fade to a light shower
  const lead: Puff[] = []
  const latest = weather.cells.filter(c => c.isLatest)
  const riskiest = [...latest].sort((a, b) => b.risk - a.risk)[0]?.path
  const faded = new Set(weather.cells.filter(c => !c.isLatest).map(c => c.path))

  if (layers.risk) {
    // a region carrying many edits pools them into one system: each burns and spreads a little less, so
    // the storm keeps its eyes and bands instead of filling the region flat
    const many = new Map<string, number>()

    for (const c of weather.cells) many.set(c.region, (many.get(c.region) ?? 0) + 1)
    for (const c of weather.cells) {
      const p = pointOf(c.path, c.region)
      const I = faded.has(c.path) ? c.risk * 0.4 : c.risk
      const into = c.path === riskiest ? lead : storm
      const crowd = c.path === riskiest ? 1 : 1 / Math.sqrt(Math.max(1, (many.get(c.region) ?? 1) / 2))
      const S = 0.55 + 0.45 * crowd

      cloud(into, rnd, p.x, p.y, (3 + 10 * I) * S, (2.4 + 7 * I) * S, Math.round(14 * (0.6 + 0.8 * I)), (0.45 + 0.95 * I) * crowd)
      cloud(into, rnd, p.x + 1.5 + 3 * I, p.y - 1 - 1.5 * I, (2 + 5 * I) * S, (1.6 + 3.5 * I) * S, Math.round(6 * (0.5 + I)), (0.14 + 0.22 * I) * crowd)
    }
  }
  if (layers.impact) {
    // a soft rain over each file that uses what changed (or, for an edit read whole, imports it
    // directly), pooling where many sit together; files further out are carried by the arms and
    // the track, so the map stays clear
    const near = weather.reach.filter(r => (r.uses === null ? r.hop === 1 : r.uses > 0))
    const every = Math.max(1, Math.ceil(near.length / 320))
    const crowd = 1 / Math.sqrt(Math.max(1, near.length / 40))
    const soft = [0, 0.5, 0.34, 0.22].map(a => a * crowd)

    near.forEach((r, i) => {
      if (i % every !== 0) return
      const p = pointOf(r.path, r.region)

      cloud(rain, rnd, p.x, p.y, 2.8, 2.3, 3, (soft[Math.min(3, r.hop)] ?? 0.1) * Math.sqrt(every) * (faded.has(r.of) ? 0.45 : 1))
    })
    // one arm per reached region, blown along the import chain from the edit
    // (the offshoot's region is reached by its dotted track instead, so the track crosses dry ground)
    const far = weather.offshoots[0]?.region
    for (const arm of weather.arms.slice(0, 6)) {
      const strength = Math.min(1, Math.log2(1 + arm.count) / Math.log2(41))
      const points = arm.chain.map(f => pointOf(f, regionOfPath(weather, f) ?? arm.region))

      if (arm.region !== far) band(rain, rnd, points, 1.3 + 1.6 * strength, (0.42 + 0.55 * strength) * (arm.hop === 1 ? 1 : arm.hop === 2 ? 0.8 : 0.65), seed)
      const end = points[points.length - 1]

      if (end !== undefined) cloud(rain, rnd, end.x, end.y, 2 + 4 * strength, 1.7 + 3 * strength, Math.round(4 + 6 * strength), 0.5 + 0.7 * strength)
    }
  }
  // one sweep from the edit to the farthest file; the forecast names the hops between
  const track = layers.impact ? weather.offshoots.slice(0, 1).flatMap(o => {
    const ends = [o.chain[0], o.chain[o.chain.length - 1]].filter(f => f !== undefined)

    return trackOf(ends.map(f => pointOf(f, regionOfPath(weather, f) ?? o.region)), seed)
  }) : []

  const leadDensity = new Float32Array(w * h)
  const stormDensity = new Float32Array(w * h)
  const rainDensity = new Float32Array(w * h)
  const warp = warpOf(w, h, seed)

  splat(leadDensity, w, h, lead, warp, 2.2)
  splat(stormDensity, w, h, storm, warp, 2.2)
  splat(rainDensity, w, h, rain, warp, 1.6)
  radar(level, wet, leadDensity, stormDensity, rainDensity, w, h, seed)
  // at most two rings, each on open ground: a ring inside the storm or over another reads as a tangle
  const rings: Field['rings'] = []

  for (const e of layers.history ? weather.expected : []) {
    const p = pointOf(e.path, e.region)
    const isInStorm = (level[Math.round(p.y) * w + Math.round(p.x)] ?? 0) >= STORM
    const isOverRing = rings.some(r => Math.abs(r.x - p.x) < 12 && Math.abs(r.y - p.y) < 11)

    if (rings.length < 2 && !isInStorm && !isOverRing) rings.push({ path: e.path, region: e.region, ...p, share: e.together / e.of })
  }
  const eyes = layers.code
    ? [...weather.cells].sort((a, b) => Number(b.isLatest) - Number(a.isLatest) || b.risk - a.risk).slice(0, 8).map(c => ({ path: c.path, ...pointOf(c.path, c.region), risk: c.risk, isLatest: c.isLatest }))
    : []

  return { w, h, level, wet, eyes, rings, track }
}

/** A file's point; a file the layout has no point for (new, untracked) gets a stable spot in its cell. */
function placer(layout: Layout, seed: number) {
  return (path: string, region: string) => {
    const known = layout.points.get(path)

    if (known !== undefined) return known
    const cell = layout.cells.find(c => c.region.id === region)?.rect ?? { x: 0, y: 0, w: layout.cols, h: layout.rows }
    const k = hashOf(path) ^ seed

    return { x: cell.x + 1 + lattice(k, 1, 3) * Math.max(1, cell.w - 2), y: (cell.y + 1) * 2 + lattice(k, 2, 5) * Math.max(1, cell.h * 2 - 3) }
  }
}

/** A cloud of puffs, dense and hot at the middle, scattering outward: one cell of precipitation. */
function cloud(out: Puff[], rnd: () => number, cx: number, cy: number, sx: number, sy: number, n: number, amp: number) {
  for (let i = 0; i < n; i++) {
    const t = Math.pow(rnd(), 1.6)
    const a = rnd() * Math.PI * 2
    const r = 0.7 + 0.6 * rnd()

    out.push({
      x: cx + Math.cos(a) * sx * t * r,
      y: cy + Math.sin(a) * sy * t * r,
      sx: Math.max(0.9, sx * (0.22 + 0.42 * (1 - t)) * (0.7 + 0.6 * rnd())),
      sy: Math.max(0.8, sy * (0.22 + 0.42 * (1 - t)) * (0.7 + 0.6 * rnd())),
      amp: (amp * (0.55 + 0.9 * (1 - t))) / Math.sqrt(n / 6),
    })
  }
}

function regionOfPath(weather: Weather, path: string): string | undefined {
  return weather.cells.find(c => c.path === path)?.region ?? weather.reach.find(r => r.path === path)?.region
}

/** Points along `chain`, each leg bowed a little, `step` pixels apart. */
function along(chain: readonly { x: number; y: number }[], step: number, seed: number, each: (x: number, y: number, t: number) => void) {
  const legs = chain.length - 1

  for (let k = 0; k < legs; k++) {
    const a = chain[k]!
    const b = chain[k + 1]!
    const dist = Math.hypot(b.x - a.x, b.y - a.y)

    if (dist < 1) continue
    const bow = Math.min(8, dist * 0.18) * (lattice(k, Math.round(a.x + b.y), seed) > 0.5 ? 1 : -1)
    const cx = (a.x + b.x) / 2 - ((b.y - a.y) / dist) * bow
    const cy = (a.y + b.y) / 2 + ((b.x - a.x) / dist) * bow
    const steps = Math.max(2, Math.round(dist / step))

    for (let i = 1; i <= steps; i++) {
      const t = i / (steps + 1)

      each((1 - t) * (1 - t) * a.x + 2 * (1 - t) * t * cx + t * t * b.x, (1 - t) * (1 - t) * a.y + 2 * (1 - t) * t * cy + t * t * b.y, (k + t) / legs)
    }
  }
}

/** An arm of rain: overlapping puffs along the chain, thinning as it travels. */
function band(out: Puff[], rnd: () => number, chain: readonly { x: number; y: number }[], width: number, amp: number, seed: number) {
  along(chain, 1.6, seed, (x, y, t) => {
    const s = width * (1 - 0.35 * t) * (0.75 + 0.5 * rnd())

    out.push({ x: x + (rnd() - 0.5) * width, y: y + (rnd() - 0.5) * width, sx: s, sy: s * 0.85, amp: (amp * (1 - 0.45 * t)) / 2 })
  })
}

/** The offshoot's dotted track: even stops along `chain`, from just past the storm to its end. */
function trackOf(chain: readonly { x: number; y: number }[], seed: number): { x: number; y: number }[] {
  const stops: { x: number; y: number }[] = []

  along(chain, 0.25, seed + 1, (x, y) => {
    const last = stops[stops.length - 1]

    // a pixel is half a row, about a column across, so distance in pixels is distance as seen
    if (last === undefined ? Math.hypot(x - chain[0]!.x, y - chain[0]!.y) > 6 : Math.hypot(x - last.x, y - last.y) >= 2.2) stops.push({ x, y })
  })
  return stops
}

/** A turbulent displacement per pixel, -1..1 on each axis, shared by every puff. */
function warpOf(w: number, h: number, seed: number): { x: Float32Array; y: Float32Array } {
  const fx = 9 / w
  const fy = 7 / h
  const x = new Float32Array(w * h)
  const y = new Float32Array(w * h)

  for (let j = 0; j < h; j++) {
    for (let i = 0; i < w; i++) {
      x[j * w + i] = (fbm(i * fx, j * fy, seed) - 0.5) * 2
      y[j * w + i] = (fbm(i * fx + 31, j * fy + 17, seed) - 0.5) * 2
    }
  }
  return { x, y }
}

/** Adds each puff's Gaussian to `density`, sampled through the warp so the edges go ragged. */
function splat(density: Float32Array, w: number, h: number, puffs: readonly Puff[], warp: { x: Float32Array; y: Float32Array }, scale: number) {
  for (const p of puffs) {
    const rx = Math.ceil(p.sx * 3 + scale)
    const ry = Math.ceil(p.sy * 3 + scale)

    for (let y = Math.max(0, Math.floor(p.y - ry)); y < Math.min(h, Math.ceil(p.y + ry)); y++) {
      for (let x = Math.max(0, Math.floor(p.x - rx)); x < Math.min(w, Math.ceil(p.x + rx)); x++) {
        const k = y * w + x
        const dx = (x + 0.5 + scale * (warp.x[k] ?? 0) - p.x) / p.sx
        const dy = (y + 0.5 + scale * (warp.y[k] ?? 0) - p.y) / p.sy

        density[k] = (density[k] ?? 0) + p.amp * Math.exp(-0.5 * (dx * dx + dy * dy))
      }
    }
  }
}

/**
 * Density to radar bins, stepped like isobands: a slow noise breathes the edges so no two
 * bands run parallel. Only the lead storm reaches the top bins, the other edits stop below
 * them, and the rain stops below both; the faintest rain is left as dry ground so a wide
 * reach never hazes the map.
 */
function radar(level: Uint8Array, wet: Uint8Array, lead: Float32Array, storm: Float32Array, rain: Float32Array, w: number, h: number, seed: number) {
  const top = BINS - 1
  const binOf = (d: number, k: number, lift = 0.5) => Math.max(0, Math.floor(top * (1 - Math.exp(-k * d)) + lift))

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x
      const l = lead[i] ?? 0
      const s = storm[i] ?? 0
      const r = rain[i] ?? 0

      if (l < 0.05 && s < 0.05 && r < 0.05) continue
      const jitter = 0.82 + 0.36 * valueNoise(x * 0.11, y * 0.16, seed + 5)

      const fire = Math.max(binOf(l * jitter, 0.3), Math.min(COOL_TOP, binOf(s * jitter * 0.55, 0.3)))
      const wash = Math.min(RAIN_TOP, binOf(r * jitter, 0.16, -1.6))

      level[i] = Math.min(top, Math.max(fire, wash))
      // the rain takes its own hue wherever it, and no storm, sets the bin
      wet[i] = wash > fire ? 1 : 0
    }
  }
}

files.hooks/render/palette.ts:
/**
 * Every colour the pane paints. The terminal's Raster paints 4 bits a channel
 * (each channel a multiple of 0x11), so each set is chosen on that grid: a colour
 * off it would be snapped channel by channel and drift in hue. The radar and rain ramps
 * walk that grid in OKLab steps of 0.02 to 0.08, mostly 0.04 to 0.06, lightness always
 * moving one way; the night radar's step from bin 5 to bin 6 (0.11) is the one wider.
 * As on a weather radar, the change storms red and its reach falls as green rain, here a
 * sage that sits with the sepia inks, so what changed and what it touches read apart at a
 * glance.
 *
 * Where Claude Code paints 256 colours (inside tmux, or where COLORTERM never says
 * truecolor) it moves each colour onto xterm's palette, and the cream paper lands on
 * a yellow. The 256 sets are drawn from that palette itself, each colour one that lands
 * on the same xterm colour whether it is rounded or matched to its nearest, so what
 * they name is what the terminal shows.
 */

/** A badge's ink and its ground. */
export type Chip = { fg: number; bg: number }

/** One printing of the chart: its ground, the radar bins over it, and the inks set on both. */
export type Inks = {
  /** the ground the pane and its map are printed on */
  paper: number
  /** radar bins, 0 = dry ground to BINS - 1 = the storm's core */
  radar: readonly number[]
  /** the hairline over each bin, two bins on, so a line tints the weather under it */
  line: readonly number[]
  /** the reach's rain, bin by bin in its own cooler hue; bin 0 is the same dry ground */
  rain: readonly number[]
  /** the hairline over each bin of rain */
  rainLine: readonly number[]
  /** the frame around the map */
  frame: number
  /** changed regions' names, the edit's note and the legend's words */
  ink: number
  /** reached regions' names, secondary notes and the title */
  muted: number
  /** the title's repo, the legend's keys, a layer switched off */
  faint: number
  /** a dry region's name: an inscription two steps off the ground, a step past its hairlines */
  nameDry: number
  /** the track, its note and the untested-risk line */
  red: number
  /** red ink set on rain, a step further from the ground so it never sinks into its own colour */
  redOnRain: number
  /** history's dashed contours and their notes */
  history: number
  /** an edit's eye: the calm point at the storm's core */
  eye: number
  /** any ink set on the storm itself */
  onStorm: number
  changed: Chip
  untested: Chip
  expected: Chip
  /** an edit the scope check says nobody asked for */
  unasked: Chip
  /** a ground darker than its inks */
  isNight: boolean
}

const paperRadar = [0xffeedd, 0xffddbb, 0xffccaa, 0xffbb99, 0xffaa88, 0xee9977, 0xee8866, 0xdd7755, 0xdd6644, 0xcc5533, 0xbb4433, 0xbb3322, 0xaa3322, 0x993322, 0x992211, 0x881111, 0x771111]
const nightRadar = [0x111111, 0x221111, 0x331111, 0x441111, 0x552211, 0x662211, 0x884422, 0x995522, 0xaa5522, 0xbb6633, 0xcc7733, 0xdd8844, 0xee9955, 0xffaa66, 0xffbb77, 0xffcc88, 0xffddaa]
// the reach's rain: a radar's green, grounded to sage, a step lighter than the storm bin for bin, so the change stays the
// loudest thing on the map
const paperRain = [0xffeedd, 0xeeeedd, 0xddeecc, 0xccddbb, 0xbbccaa, 0xaabb99, 0x99aa88, 0x889977, 0x778866, 0x667755, 0x556644, 0x445533, 0x334422, 0x223311, 0x112211, 0x112200, 0x001100]
const nightRain = [0x111111, 0x112211, 0x222211, 0x223311, 0x334422, 0x445533, 0x556644, 0x667755, 0x778866, 0x889977, 0x99aa88, 0xaabb99, 0xbbccaa, 0xccddbb, 0xddeecc, 0xeeeedd, 0xeeffee]

/**
 * Each bin's hairline: two bins on, the dry ground's a neutral step off it. A 256 ramp repeats
 * a colour across bins, so its hairline is the first colour on that shows darker.
 */
const linesOf = (radar: readonly number[], dry: number, shows = (c: number) => c) =>
  radar.map((c, k) => (k === 0 ? dry : (radar.slice(k + 2).find(next => shows(next) !== shows(c)) ?? radar[radar.length - 1]!)))

/** Warm cream paper, apricot rain deepening through terracotta to a deep-red core, sepia inks. */
export const PAPER_INKS: Inks = {
  paper: 0xffeedd,
  radar: paperRadar,
  line: linesOf(paperRadar, 0xeeddcc),
  rain: paperRain,
  rainLine: linesOf(paperRain, 0xeeddcc),
  frame: 0xddccbb,
  ink: 0x332211,
  muted: 0x776655,
  faint: 0xaa9988,
  nameDry: 0xddccbb,
  red: 0xaa3322,
  redOnRain: 0x661111,
  history: 0x993311,
  eye: 0xffeedd,
  onStorm: 0xffeedd,
  changed: { fg: 0xffeedd, bg: 0xcc5533 },
  untested: { fg: 0x776655, bg: 0xeeddcc },
  expected: { fg: 0x774411, bg: 0xffdd99 },
  unasked: { fg: 0xffeedd, bg: 0x332211 },
  isNight: false,
}

/** The terminal's own near-black with the weather burning up through it: the same chart at night. */
export const NIGHT_INKS: Inks = {
  paper: 0x111111,
  radar: nightRadar,
  line: linesOf(nightRadar, 0x222222),
  rain: nightRain,
  rainLine: linesOf(nightRain, 0x222222),
  frame: 0x333333,
  ink: 0xeeddcc,
  muted: 0xaa9988,
  faint: 0x776655,
  nameDry: 0x443333,
  red: 0xff7755,
  redOnRain: 0xffaa88,
  history: 0x997744,
  eye: 0xffffee,
  onStorm: 0x111111,
  changed: { fg: 0x111111, bg: 0xcc6633 },
  untested: { fg: 0xaa9988, bg: 0x333333 },
  expected: { fg: 0xddaa55, bg: 0x443311 },
  unasked: { fg: 0x111111, bg: 0xeeddcc },
  isNight: true,
}

/** How many radar bins every set of inks colours. */
export const BINS = paperRadar.length

/** The first bin of the storm proper: inks set on it turn to `onStorm`. */
export const STORM = 10

/** Bins every edit but the riskiest may reach: the top four belong to the lead storm. */
export const COOL_TOP = 12

/** Bins the reach's rain may reach: the brightest and deepest bins belong to the edit. */
export const RAIN_TOP = 7

/** How many colours the terminal paints: 24-bit, or xterm's 256. */
export type Colors = 'truecolor' | '256'

/** The six levels of each channel in xterm's colour cube. */
const CUBE = [0x00, 0x5f, 0x87, 0xaf, 0xd7, 0xff]

/** The colour xterm colour `i` (16 to 255) shows. */
export function xtermColour(i: number): number {
  if (i >= 232) return 0x010101 * (8 + 10 * (i - 232))
  const k = i - 16

  return (CUBE[Math.floor(k / 36)]! << 16) | (CUBE[Math.floor(k / 6) % 6]! << 8) | CUBE[k % 6]!
}

const distance = (p: number, q: number) => (((p >> 16) & 255) - ((q >> 16) & 255)) ** 2 + (((p >> 8) & 255) - ((q >> 8) & 255)) ** 2 + ((p & 255) - (q & 255)) ** 2

/** The xterm colour nearest `c`: how the Raster paints `c` in 256 colours (0xbb7744 shows as 0xaf875f). */
export function xtermOf(c: number): number {
  let best = 16

  for (let i = 17; i < 256; i++) if (distance(c, xtermColour(i)) < distance(c, xtermColour(best))) best = i
  return best
}

/**
 * The xterm colour Claude Code's own text takes for `c` in 256 colours: each channel rounds to
 * one of six even steps of 0x33 (0xbb7744 shows as 0xd7875f), an even grey to the grey ramp.
 */
export function roundedXtermOf(c: number): number {
  const [r, g, b] = [(c >> 16) & 255, (c >> 8) & 255, c & 255]

  if (r === g && g === b) return r < 8 ? 16 : r > 248 ? 231 : Math.round(((r - 8) / 247) * 24) + 232
  return 16 + 36 * Math.round(r / 51) + 6 * Math.round(g / 51) + Math.round(b / 51)
}

/** What a 256-colour terminal shows for `c` in the Raster. */
export const shown256 = (c: number): number => xtermColour(xtermOf(c))

// every 4-bit colour that lands on one xterm colour both ways, by that colour, the nearest to it first
const LANDINGS = new Map<number, number[]>()

for (let n = 0; n < 4096; n++) {
  const c = 0x11 * (((n >> 8) << 16) | (((n >> 4) & 15) << 8) | (n & 15))
  const i = xtermOf(c)

  if (roundedXtermOf(c) === i) LANDINGS.set(i, [...(LANDINGS.get(i) ?? []), c])
}
for (const [i, cs] of LANDINGS) cs.sort((p, q) => distance(p, xtermColour(i)) - distance(q, xtermColour(i)))

/**
 * A 4-bit colour the terminal paints as xterm colour `i`; the `nth` gives another of them, so
 * a ramp can repeat a colour across bins under names the sheet still tells apart.
 */
function xterm(i: number, nth = 0): number {
  const cs = LANDINGS.get(i)

  if (cs === undefined || cs[nth] === undefined) throw new Error(`no 4-bit colour lands on xterm ${i} (${nth})`)
  return cs[nth]!
}

/** A ramp of xterm colours, each repeat under its next name. */
const rampOf = (indices: readonly number[]) => indices.map((i, k) => xterm(i, indices.slice(0, k).filter(j => j === i).length))

/** White paper, apricot rain deepening through terracotta to a deep-red core: the paper chart in xterm's colours. */
const paperRadar256 = rampOf([231, 223, 223, 216, 216, 173, 173, 173, 167, 167, 167, 88, 88, 88, 88, 52, 52])
/** Near-black with the weather burning up through red and amber: the night chart in xterm's colours. */
const nightRadar256 = rampOf([233, 52, 52, 52, 88, 88, 88, 131, 131, 173, 173, 180, 180, 216, 216, 223, 223])
/** The reach's sage rain in xterm's colours, on each ground. */
const paperRain256 = rampOf([231, 194, 194, 151, 151, 108, 107, 107, 101, 101, 65, 64, 64, 58, 58, 22, 22])
const nightRain256 = rampOf([233, 22, 22, 22, 58, 58, 65, 101, 101, 107, 107, 108, 151, 151, 194, 194, 194])

export const PAPER_INKS_256: Inks = {
  paper: paperRadar256[0]!,
  radar: paperRadar256,
  line: linesOf(paperRadar256, xterm(253), shown256),
  rain: paperRain256,
  rainLine: linesOf(paperRain256, xterm(253), shown256),
  frame: xterm(253),
  ink: xterm(236),
  muted: xterm(243),
  faint: xterm(248),
  nameDry: xterm(253),
  red: xterm(124),
  redOnRain: xterm(52),
  history: xterm(130),
  eye: xterm(231),
  onStorm: xterm(231),
  changed: { fg: xterm(231), bg: xterm(167) },
  untested: { fg: xterm(243), bg: xterm(253) },
  expected: { fg: xterm(94), bg: xterm(222) },
  unasked: { fg: xterm(231), bg: xterm(236) },
  isNight: false,
}

export const NIGHT_INKS_256: Inks = {
  paper: nightRadar256[0]!,
  radar: nightRadar256,
  line: linesOf(nightRadar256, xterm(235), shown256),
  rain: nightRain256,
  rainLine: linesOf(nightRain256, xterm(235), shown256),
  frame: xterm(236),
  ink: xterm(253),
  muted: xterm(248),
  faint: xterm(243),
  nameDry: xterm(238),
  red: xterm(209),
  redOnRain: xterm(216),
  history: xterm(137),
  eye: xterm(231),
  onStorm: xterm(233),
  changed: { fg: xterm(233), bg: xterm(173) },
  untested: { fg: xterm(248), bg: xterm(236) },
  expected: { fg: xterm(179), bg: xterm(236) },
  unasked: { fg: xterm(233), bg: xterm(253) },
  isNight: true,
}

/** The inks for a ground on a terminal that paints `colors`. */
export const inksOf = (ground: 'paper' | 'night', colors: Colors): Inks =>
  colors === '256' ? (ground === 'night' ? NIGHT_INKS_256 : PAPER_INKS_256) : ground === 'night' ? NIGHT_INKS : PAPER_INKS

/**
 * How many colours Claude Code paints for a terminal's environment, decided as it decides:
 * 256 inside tmux; 24-bit where COLORTERM is truecolor or the terminal is kitty, Ghostty or
 * iTerm; 256 everywhere else.
 */
export function colorsOf(env: Readonly<Record<string, string | undefined>>): Colors {
  if (env.TMUX) return '256'
  return env.COLORTERM === 'truecolor' || env.TERM === 'xterm-kitty' || env.TERM === 'xterm-ghostty' || env.TERM_PROGRAM === 'iTerm.app' ? 'truecolor' : '256'
}

